use vstd::prelude::*;

verus! {
    // Splits a non‐empty vector `list` of i32 at index `l`, with 0 < l < list.len().
    // Returns two vectors `first` and `second` such that
    //   first == list[0 .. l]
    //   second == list[l .. list.len()]
    fn split_array(list: &Vec<i32>, l: usize) -> (first: Vec<i32>, second: Vec<i32>)
        requires
            list.len() > 0,
            l > 0,
            l < list.len(),
        ensures
            first.len() == l,
            second.len() == list.len() - l,
            // `list@` is the mathematical sequence corresponding to `list`.
            // `slice(lo, hi)` denotes the subsequence in [lo, hi).
            first@ == list@.slice(0, l),
            second@ == list@.slice(l, list.len()),
    {
        let mut first: Vec<i32> = Vec::new();
        let mut second: Vec<i32> = Vec::new();
        let mut idx: usize = 0;
        // We traverse every index of `list`, pushing into `first` or `second`
        // depending on whether idx < l.
        while idx < list.len()
            invariant
                // idx walks from 0 up to list.len()
                idx <= list.len(),
                // `first.len()` grows up to l
                first.len() == if idx < l { idx } else { l },
                // `second.len()` is zero until idx >= l, then grows up to list.len() - l
                second.len() == if idx < l { 0 } else { idx - l },
                // the contents of `first` so far match the prefix of `list`
                first@ == list@.slice(0, first.len()),
                // the contents of `second` so far match the slice of `list` from l
                second@ == list@.slice(l, l + second.len()),
            decreases
                list.len() - idx,
        {
            let x = list[idx];
            if idx < l {
                first.push(x);
                // after push, first.len() = old first.len()+1 <= l
                assert(first.len() <= l);
            } else {
                second.push(x);
                // after push, second.len() = old second.len()+1 <= list.len()-l
                assert(second.len() <= list.len() - l);
            }
            idx += 1;
        }
        (first, second)
    }
}

